<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\UserAccessTemporalCodeUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserAccessTemporalCodeUserAttributeHolder
{
    protected UserAccessTemporalCodeUserVO|UserRef|null $user = null;
    protected bool $userAssigned = false;

    public function getUserOrDefault(UserAccessTemporalCodeUserVO $user): UserAccessTemporalCodeUserVO
    {
        if ($this->userAssigned) {
            \assert(null !== $this->user);
            return UserAccessTemporalCodeUserVO::from($this->user);
        } else {
            return $user;
        }
    }
    public function user(UserAccessTemporalCodeUserVO|UserRef $user): static
    {
        $this->user = $user;
        $this->userAssigned = true;
        return $this;
    }
    public function getUser(): ?UserRef
    {
        return $this->user instanceof UserAccessTemporalCodeUserVO ? $this->user->value() : $this->user;
    }
    public function isUserAssigned(): bool
    {
        return $this->userAssigned;
    }
    public function writeUserTo(mixed $att): void
    {
        if ($this->userAssigned) {
            \assert(null !== $this->user);
            $att->user($this->user);
        }
    }
    public function readUserFrom(mixed $att): void
    {
        if ($att->isUserAssigned()) {
            $user = $att->getUser();
            \assert(null !== $user);
            $this->user($user);
        }
    }
    public function unsetUser(): static
    {
        $this->userAssigned = false;
        return $this;
    }
    protected function withDefaultUser(): void
    {
    }
    protected function withAssertedUserRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->userAssigned = $this->userAssigned) {
            $value->user = UserAccessTemporalCodeUserVO::tryFrom($this->user, $errorsList);
        }
    }
}
